    /// <summary>
    /// 清理宝可梦名称中的特殊字符
    /// </summary>
    /// <param name="name">原始名称</param>
    /// <returns>清理后的名称</returns>
    public static string CleanPokemonName(string name)
    {
        if (string.IsNullOrEmpty(name))
            return string.Empty;

        return name.Replace("-*", "")
                  .Replace("♀", "-f")
                  .Replace("♂", "-m")
                  .Trim();
    }

    /// <summary>
    /// 解析宝可梦位置信息
    /// </summary>
    /// <param name="position">位置字符串（如 "p1a", "p2b"）</param>
    /// <returns>元组：(玩家位置, 场上位置)</returns>
    public static (PlayerPosition player, int slot) ParsePosition(string position)
    {
        if (string.IsNullOrEmpty(position) || position.Length < 3)
            return (PlayerPosition.Player1, 0);

        var playerPos = position[1] == '1' ? PlayerPosition.Player1 : PlayerPosition.Player2;
        var slot = position[2] switch
        {
            'a' => 0,
            'b' => 1,
            'c' => 2,
            'd' => 3,
            _ => 0
        };

        return (playerPos, slot);
    }

    /// <summary>
    /// 解析HP信息
    /// </summary>
    /// <param name="hpString">HP字符串（如 "100/100", "50/100 par"）</param>
    /// <returns>元组：(当前HP, 最大HP, 状态)</returns>
    public static (int current, int max, string status) ParseHP(string hpString)
    {
        if (string.IsNullOrEmpty(hpString))
            return (0, 0, string.Empty);

        var parts = hpString.Split(' ');
        var hpPart = parts[0];
        var status = parts.Length > 1 ? parts[1] : string.Empty;

        var hpValues = hpPart.Split('/');
        if (hpValues.Length == 2 && 
            int.TryParse(hpValues[0], out var current) && 
            int.TryParse(hpValues[1], out var max))
        {
            return (current, max, status);
        }

        return (0, 0, status);
    }

    /// <summary>
    /// 解析百分比HP
    /// </summary>
    /// <param name="hpString">HP字符串（如 "50%", "100%"）</param>
    /// <returns>HP百分比（0-100）</returns>
    public static double ParseHPPercentage(string hpString)
    {
        if (string.IsNullOrEmpty(hpString))
            return 0;

        var cleanString = hpString.Replace("%", "").Trim();
        if (double.TryParse(cleanString, out var percentage))
        {
            return Math.Max(0, Math.Min(100, percentage));
        }

        return 0;
    }

