    /// <summary>
    /// 验证对战格式
    /// </summary>
    /// <param name="format">格式字符串</param>
    /// <returns>是否为有效格式</returns>
    public static bool IsValidFormat(string format)
    {
        if (string.IsNullOrEmpty(format))
            return false;

        var validFormats = new[]
        {
            "gen9ou", "gen9uu", "gen9ru", "gen9nu", "gen9pu",
            "gen9doubles", "gen9vgc2024", "gen9battlestadiumsingles",
            "gen8ou", "gen7ou", "gen6ou", "gen5ou", "gen4ou", "gen3ou",
            "gen9randombattle", "gen9hackmons", "gen9almostanyability"
        };

        return validFormats.Contains(format.ToLowerInvariant());
    }

    /// <summary>
    /// 生成随机房间ID
    /// </summary>
    /// <returns>随机房间ID</returns>
    public static string GenerateRoomId()
    {
        var random = new Random();
        const string chars = "abcdefghijklmnopqrstuvwxyz0123456789";
        return new string(Enumerable.Repeat(chars, 8)
                                  .Select(s => s[random.Next(s.Length)])
                                  .ToArray());
    }

    /// <summary>
    /// 解析回合数
    /// </summary>
    /// <param name="turnString">回合字符串</param>
    /// <returns>回合数</returns>
    public static int ParseTurn(string turnString)
    {
        if (string.IsNullOrEmpty(turnString))
            return 0;

        if (int.TryParse(turnString, out var turn))
        {
            return Math.Max(0, turn);
        }

        return 0;
    }

    /// <summary>
    /// 检查是否为有效的宝可梦名称
    /// </summary>
    /// <param name="name">名称</param>
    /// <returns>是否有效</returns>
    public static bool IsValidPokemonName(string name)
    {
        if (string.IsNullOrWhiteSpace(name))
            return false;

        // 基本的名称验证规则
        return name.Length <= 20 && 
               !name.Contains('|') && 
               !name.Contains('\n') &&
               !name.Contains('\r');
    }

    /// <summary>
    /// 格式化时间戳
