    public static string FormatTimestamp(DateTime timestamp)
    {
        return timestamp.ToString("yyyy-MM-dd HH:mm:ss");
    }

    /// <summary>
    /// 解析对战结果
    /// </summary>
    /// <param name="winner">获胜者名称</param>
    /// <param name="player1">玩家1名称</param>
    /// <param name="player2">玩家2名称</param>
    /// <returns>对战结果</returns>
    public static BattleResult ParseBattleResult(string winner, string player1, string player2)
    {
        if (string.IsNullOrEmpty(winner))
            return BattleResult.Draw;

        if (winner.Equals(player1, StringComparison.OrdinalIgnoreCase))
            return BattleResult.Player1Win;
        
        if (winner.Equals(player2, StringComparison.OrdinalIgnoreCase))
            return BattleResult.Player2Win;

        return BattleResult.Draw;
    }
